DO $qa$
DECLARE m uuid:=gen_random_uuid();s uuid:=gen_random_uuid();cs uuid:=gen_random_uuid();cs2 uuid:=gen_random_uuid();c uuid:=gen_random_uuid();u uuid:=gen_random_uuid();u2 uuid:=gen_random_uuid();cust uuid:=gen_random_uuid();b uuid:=gen_random_uuid();b2 uuid:=gen_random_uuid();d uuid:=gen_random_uuid();d2 uuid:=gen_random_uuid();o uuid:=gen_random_uuid();o2 uuid:=gen_random_uuid();o3 uuid:=gen_random_uuid();rid uuid;cid uuid;complaint uuid;foreign_case uuid;gr bigint;desk1 text:='qa-'||gen_random_uuid();desk2 text:='qa-'||gen_random_uuid();res jsonb; blocked boolean;checks int:=0; n bigint:=-1000000000000-floor(random()*1e12)::bigint; phone text:='7'||lpad((floor(random()*1e8))::text,8,'0');
BEGIN
 BEGIN
 INSERT INTO public.ff_branches(id,code,name) VALUES(b,'qa-a10-'||b,'A10 QA one'),(b2,'qa-a10-'||b2,'A10 QA two');
 INSERT INTO auth.users(id) VALUES(m),(s),(cs),(cs2),(c),(u),(u2);
 INSERT INTO auth.users(id,phone,phone_confirmed_at) VALUES(cust,'967'||phone,now());
 INSERT INTO public.ff_profiles(user_id,display_name,role,active) VALUES(m,'A10 QA manager','manager',true),(s,'A10 QA supervisor','supervisor',true),(cs,'A10 QA CS','customer_service',true),(cs2,'A10 QA CS2','customer_service',true),(c,'A10 QA cashier','cashier',true),(u,'A10 QA driver','driver',true),(u2,'A10 QA driver2','driver',true) ON CONFLICT(user_id) DO UPDATE SET role=excluded.role,active=true;
 DELETE FROM public.ff_profiles WHERE user_id=cust;
 INSERT INTO public.ff_user_branches(user_id,branch_id) VALUES(s,b),(c,b),(cs,b),(cs2,b2),(u,b),(u2,b2);
 INSERT INTO public.ff_drivers(id,name,branch_id) VALUES(d,'A10 QA driver',b),(d2,'A10 QA other driver',b2);
 INSERT INTO public.ff38_driver_presence(driver_id,state,checked_in_at,last_seen_at) VALUES(d,'busy',now()-interval '2 hours',now()),(d2,'busy',now()-interval '2 hours',now()) ON CONFLICT(driver_id) DO UPDATE SET state='busy',checked_in_at=excluded.checked_in_at,last_seen_at=excluded.last_seen_at;
 INSERT INTO public.ff38_driver_links(user_id,driver_id) VALUES(u,d),(u2,d2);
 INSERT INTO public.ff_orders(id,order_number,branch_id,phone_snapshot,driver_id,status,created_by,created_at,delivered_at) VALUES(o,n,b,phone,d,'delivered',cs,now()-interval '1 hour',now()-interval '20 minutes'),(o2,n-1,b2,'000000000',d2,'delivered',cs2,now()-interval '1 hour',now()-interval '20 minutes'),(o3,n-2,b,phone,d,'sent',cs,now()-interval '1 hour',NULL);
 INSERT INTO public.ff38_delivery_tasks(order_id,driver_id,phase,cashier_stage,delivered_at) VALUES(o,d,'delivered','handed_over',now()-interval '20 minutes'),(o2,d2,'delivered','handed_over',now()-interval '20 minutes'),(o3,d,'assigned','handed_over',NULL);
 INSERT INTO public.ff_luxe_cashier_desks(code,label,branch_id,sort_order) VALUES(desk1,'QA desk1',b,1),(desk2,'QA desk2',b,2);
 INSERT INTO public.ff_luxe_cashier_staff_desks(user_id,desk_code,assigned_by) VALUES(c,desk1,m);
 INSERT INTO public.ff49_cashier_receipts(order_id,received_by,received_at) VALUES(o3,c,now()-interval '30 minutes');
 INSERT INTO public.ff_luxe_cashier_order_desks(order_id,desk_code) VALUES(o,desk2),(o3,desk1);
 PERFORM set_config('request.jwt.claim.sub',u::text,true);SET LOCAL ROLE authenticated;
 res:=public.ff_a10_driver_rating_queue();
 IF NOT EXISTS(SELECT FROM jsonb_array_elements(res) x WHERE x->>'id'=o::text) OR EXISTS(SELECT FROM jsonb_array_elements(res) x WHERE x->>'id' IN(o2::text,o3::text)) THEN RAISE EXCEPTION 'Rating queue scope';END IF;checks:=checks+1;
 blocked:=false;BEGIN PERFORM public.ff_luxe_driver_rate_order(o3,5,5,5,5,'early');EXCEPTION WHEN insufficient_privilege THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Premature rating';END IF;checks:=checks+1;
 PERFORM public.ff_luxe_driver_rate_order(o,1,2,3,4,'QA private driver note');
 IF EXISTS(SELECT FROM jsonb_array_elements(public.ff_a10_driver_rating_queue()) x WHERE x->>'id'=o::text) THEN RAISE EXCEPTION 'Rated queue entry';END IF;checks:=checks+1;
 blocked:=false;BEGIN PERFORM public.ff_luxe_driver_rate_order(o,5,5,5,5,'overwrite');EXCEPTION WHEN OTHERS THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Duplicate driver review';END IF;checks:=checks+1;
 res:=public.ff_luxe_driver_grievance(o,'delivery_fee','QA private grievance details');cid:=(res->>'case_id')::uuid;gr:=(res->>'id')::bigint;
 IF cid IS NULL OR public.ff41_case_detail(cid)#>>'{item,kind}'<>'staff_grievance' THEN RAISE EXCEPTION 'Grievance not in unified center';END IF;checks:=checks+1;
 blocked:=false;BEGIN PERFORM public.ff_luxe_driver_grievance(o2,'other','QA foreign order grievance');EXCEPTION WHEN insufficient_privilege THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Foreign grievance';END IF;checks:=checks+1;
 RESET ROLE;PERFORM set_config('request.jwt.claim.sub',cs::text,true);SET LOCAL ROLE authenticated;
 PERFORM public.ff_luxe_rate_driver_cs(o,2,'QA private CS note');
 blocked:=false;BEGIN PERFORM public.ff_luxe_rate_driver_cs(o,5,'overwrite');EXCEPTION WHEN OTHERS THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Duplicate CS rating';END IF;checks:=checks+1;
 blocked:=false;BEGIN PERFORM public.ff_luxe_rate_driver_cs(o2,2,'other CS order');EXCEPTION WHEN insufficient_privilege THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Foreign CS rating';END IF;checks:=checks+1;
 res:=public.ff41_case_create('customer_complaint','QA local complaint','QA complaint details',b,o,'normal',NULL,NULL,'other');complaint:=(res->>'case_id')::uuid;
 RESET ROLE;PERFORM set_config('request.jwt.claim.sub',cs2::text,true);SET LOCAL ROLE authenticated;
 res:=public.ff41_case_create('customer_complaint','QA foreign complaint','QA foreign complaint details',b2,o2,'normal',NULL,NULL,'other');foreign_case:=(res->>'case_id')::uuid;
 RESET ROLE;PERFORM set_config('request.jwt.claim.sub',s::text,true);SET LOCAL ROLE authenticated;
 res:=public.ff41_case_list(NULL,NULL,100);
 IF EXISTS(SELECT FROM jsonb_array_elements(res->'items') x WHERE x->>'id' IN(cid::text,foreign_case::text)) OR NOT EXISTS(SELECT FROM jsonb_array_elements(res->'items') x WHERE x->>'id'=complaint::text) THEN RAISE EXCEPTION 'Case list scope';END IF;checks:=checks+1;
 blocked:=false;BEGIN PERFORM public.ff41_case_detail(foreign_case);EXCEPTION WHEN insufficient_privilege THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Foreign case detail';END IF;checks:=checks+1;
 blocked:=false;BEGIN PERFORM public.ff41_case_comment(cid,'unauthorized private note');EXCEPTION WHEN insufficient_privilege THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Private grievance comment';END IF;checks:=checks+1;
 blocked:=false;BEGIN PERFORM public.ff_case_alert_read(foreign_case);EXCEPTION WHEN insufficient_privilege THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Foreign alert acknowledgment';END IF;checks:=checks+1;
 blocked:=false;BEGIN PERFORM public.ff_luxe_rating_summary_period(public.ff_business_date(now()),public.ff_business_date(now()),b2);EXCEPTION WHEN insufficient_privilege THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Foreign ratings summary';END IF;checks:=checks+1;
 RESET ROLE;PERFORM set_config('request.jwt.claim.sub',c::text,true);SET LOCAL ROLE authenticated;
 blocked:=false;BEGIN PERFORM public.ff_luxe_rate_driver_cashier(o,5,'other desk');EXCEPTION WHEN insufficient_privilege THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Foreign desk rating';END IF;checks:=checks+1;
 blocked:=false;BEGIN PERFORM public.ff41_case_detail(complaint);EXCEPTION WHEN insufficient_privilege THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Foreign desk complaint';END IF;checks:=checks+1;
 PERFORM public.ff_luxe_rate_driver_cashier(o3,3,'QA handed over');
 IF NOT public.ff_a10_cashier_coordination(o3,4,'QA preparation coordination') THEN RAISE EXCEPTION 'Coordination not saved';END IF;checks:=checks+1;
 blocked:=false;BEGIN PERFORM public.ff_a10_cashier_coordination(o3,5,'overwrite');EXCEPTION WHEN OTHERS THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Coordination duplicate';END IF;checks:=checks+1;
 blocked:=false;BEGIN PERFORM public.ff_a10_cashier_coordination(o,5,'foreign');EXCEPTION WHEN insufficient_privilege THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Coordination scope';END IF;checks:=checks+1;
 res:=public.ff_luxe_cashier_completed_orders(60,0);IF NOT EXISTS(SELECT FROM jsonb_array_elements(res->'items') x WHERE x->>'id'=o3::text AND (x->>'coordination_stars')::int=4 AND NOT (x->>'can_rate_coordination')::boolean) THEN RAISE EXCEPTION 'Coordination state missing %',res;END IF;checks:=checks+1;
 RESET ROLE;PERFORM set_config('request.jwt.claim.sub',cust::text,true);SET LOCAL ROLE authenticated;
 PERFORM public.ff_a10_customer_rate(o,2,'QA customer note');
 blocked:=false;BEGIN PERFORM public.ff_a10_customer_rate(o,5,'overwrite');EXCEPTION WHEN insufficient_privilege THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Duplicate customer rating';END IF;checks:=checks+1;
 blocked:=false;BEGIN PERFORM public.ff_a10_customer_rate(o2,5,'foreign order');EXCEPTION WHEN insufficient_privilege THEN blocked:=true;END;IF NOT blocked THEN RAISE EXCEPTION 'Foreign customer rating';END IF;checks:=checks+1;
 RESET ROLE;
 SELECT id INTO rid FROM public.ff51_driver_ratings WHERE order_id=o AND rater_role='customer_service';
 PERFORM set_config('request.jwt.claim.sub',m::text,true);SET LOCAL ROLE authenticated;
 res:=public.ff_a10_escalate_rating(rid,'QA manual quality followup without penalty');
 IF res->>'ok'<>'true' OR (public.ff_a10_escalate_rating(rid,'QA duplicate followup') ->>'already_exists')<>'true' THEN RAISE EXCEPTION 'Manual escalation idempotency';END IF;checks:=checks+1;
 PERFORM public.ff41_case_transition(cid,'in_review',NULL);
 PERFORM public.ff41_case_transition(cid,'resolved','QA verified response');
 PERFORM public.ff41_case_transition(cid,'closed',NULL);
 RESET ROLE;
 IF (SELECT status FROM public.ff_luxe_driver_grievances WHERE id=gr)<>'resolved' OR (SELECT count(*) FROM public.ff41_case_events WHERE case_id=cid)<>4 THEN RAISE EXCEPTION 'Grievance lifecycle audit';END IF;checks:=checks+1;
 IF (SELECT rating FROM public.ff_orders WHERE id=o)<>2 OR (SELECT rating_note FROM public.ff_orders WHERE id=o)<>'QA customer note' OR (SELECT stars FROM public.ff51_driver_ratings WHERE id=rid)<>2 OR (SELECT status FROM public.ff_orders WHERE id=o)<>'delivered' THEN RAISE EXCEPTION 'Ratings mutated or blocked order';END IF;checks:=checks+1;
 RAISE EXCEPTION 'QA rollback' USING ERRCODE='ZQA11';
 EXCEPTION WHEN SQLSTATE 'ZQA11' THEN NULL;END;
 IF checks<>24 OR EXISTS(SELECT FROM public.ff_branches WHERE id IN(b,b2)) THEN RAISE EXCEPTION 'Incomplete QA rollback %',checks;END IF;
END $qa$;
SELECT 'PASS A10: 24 quality, private grievance lifecycle, rating identity and scope assertions' result;